// DAY 0 — Deliver the lead magnet / welcome email
const C = $('Setup Client Variables').item.json;
const L = $('Capture Lead Data').item.json;

const sig = `<div style="margin-top:40px;display:flex;align-items:center;border-top:1px solid #e2e8f0;padding-top:30px;">
  <img src="${C.photoUrl}" alt="${C.senderFirstName}" style="width:70px;height:70px;border-radius:50%;margin-right:20px;object-fit:cover;border:2px solid #e2e8f0;">
  <div>
    <p style="margin:0;font-weight:800;font-size:18px;color:#1a1a2e;">${C.senderFullName}</p>
    <p style="margin:4px 0 0 0;font-size:14px;color:#64748b;font-weight:600;">${C.senderTitle}</p>
    <p style="margin:4px 0 0 0;font-size:13px;"><a href="${C.siteUrl}" style="color:#3b82f6;text-decoration:none;font-weight:600;">${C.siteUrl.replace('https://','')}</a></p>
  </div>
</div>`;

// ============================================================
// EDIT EMAIL BODY BELOW — Keep the wrapper, change the content
// ============================================================
const body = `
  <h2 style="font-size:24px;font-weight:800;color:#1a1a2e;margin-bottom:24px;letter-spacing:-0.5px;">Great connecting, ${L.firstName}!</h2>
  <p style="font-size:16px;margin-bottom:20px;">Hi ${L.firstName},</p>
  <p style="font-size:16px;margin-bottom:20px;">Thanks for reaching out — here's the ${C.leadMagnetTitle} I promised you:</p>
  <div style="text-align:center;margin:40px 0;background:linear-gradient(135deg,rgba(59,130,246,0.05),rgba(139,92,246,0.05));padding:40px 20px;border-radius:12px;border:1px solid rgba(59,130,246,0.1);">
    <h3 style="margin-top:0;color:#1a1a2e;font-size:18px;margin-bottom:8px;">${C.leadMagnetTitle}</h3>
    <p style="font-size:14px;color:#64748b;margin-bottom:24px;">EDIT THIS LINE — describe what they're getting and why it matters</p>
    <a href="${C.leadMagnetUrl}" style="background-color:#3b82f6;color:white;padding:16px 32px;text-decoration:none;border-radius:8px;font-weight:bold;font-size:16px;display:inline-block;box-shadow:0 4px 14px rgba(59,130,246,0.3);">Access Now →</a>
  </div>
  <p style="font-size:16px;margin-bottom:20px;">I'll follow up in a couple of days — I want to make sure you got it and point you to the most important part.</p>
  <p style="font-size:16px;margin-bottom:30px;">Talk soon,</p>
`;
// ============================================================

const html = `<div style="font-family:'Helvetica Neue',Arial,sans-serif;color:#1a1a2e;max-width:600px;margin:0 auto;padding:40px 20px;line-height:1.6;background-color:#ffffff;border-top:5px solid #3b82f6;border-radius:8px;box-shadow:0 4px 6px rgba(0,0,0,0.05);">
  <div style="text-align:center;margin-bottom:40px;"><img src="${C.logoUrl}" alt="${C.companyName}" style="max-height:50px;"></div>
  ${body}
  ${sig}
</div>`;

return [{ json: { html, subject: `Great connecting, ${L.firstName} — here's what I promised`, to: L.email } }];

// DAY 2 — Point to key insight / value from what they received
const C = $('Setup Client Variables').item.json;
const L = $('Capture Lead Data').item.json;

const sig = `<div style="margin-top:40px;display:flex;align-items:center;border-top:1px solid #e2e8f0;padding-top:30px;">
  <img src="${C.photoUrl}" alt="${C.senderFirstName}" style="width:70px;height:70px;border-radius:50%;margin-right:20px;object-fit:cover;border:2px solid #e2e8f0;">
  <div>
    <p style="margin:0;font-weight:800;font-size:18px;color:#1a1a2e;">${C.senderFullName}</p>
    <p style="margin:4px 0 0 0;font-size:14px;color:#64748b;font-weight:600;">${C.senderTitle}</p>
    <p style="margin:4px 0 0 0;font-size:13px;"><a href="${C.siteUrl}" style="color:#3b82f6;text-decoration:none;font-weight:600;">${C.siteUrl.replace('https://','')}</a></p>
  </div>
</div>`;

// ============================================================
// EDIT EMAIL BODY — Day 2: Highlight a key insight or tip
// Goal: deliver more value, build trust, NOT a hard pitch yet
// ============================================================
const body = `
  <h2 style="font-size:24px;font-weight:800;color:#1a1a2e;margin-bottom:24px;letter-spacing:-0.5px;">EDIT: Subject-level hook goes here</h2>
  <p style="font-size:16px;margin-bottom:20px;">Hi ${L.firstName},</p>
  <p style="font-size:16px;margin-bottom:20px;">A couple of days ago I sent you the ${C.leadMagnetTitle}.</p>
  <p style="font-size:16px;margin-bottom:20px;">I wanted to draw your attention to one thing specifically: <strong>EDIT — name the key insight or section they should focus on.</strong></p>
  <p style="font-size:16px;margin-bottom:20px;">EDIT — 1-2 sentences explaining why this insight matters for someone in their situation.</p>
  <div style="background-color:#f8fafc;padding:24px;border-left:4px solid #8b5cf6;border-radius:4px;margin:30px 0;">
    <p style="font-size:15px;margin:0;font-style:italic;color:#475569;">EDIT — Compelling callout quote or insight. Then soft mention of ${C.offerName} if they want to go deeper.</p>
  </div>
  <div style="text-align:center;margin:40px 0;">
    <a href="${C.bookingUrl}" style="background-color:#3b82f6;color:white;padding:16px 32px;text-decoration:none;border-radius:8px;font-weight:bold;font-size:16px;display:inline-block;box-shadow:0 4px 14px rgba(59,130,246,0.3);">EDIT — CTA Button Text</a>
  </div>
  <p style="font-size:16px;margin-bottom:30px;">Talk soon,</p>
`;
// ============================================================

const html = `<div style="font-family:'Helvetica Neue',Arial,sans-serif;color:#1a1a2e;max-width:600px;margin:0 auto;padding:40px 20px;line-height:1.6;background-color:#ffffff;border-top:5px solid #3b82f6;border-radius:8px;box-shadow:0 4px 6px rgba(0,0,0,0.05);">
  <div style="text-align:center;margin-bottom:40px;"><img src="${C.logoUrl}" alt="${C.companyName}" style="max-height:50px;"></div>
  ${body}
  ${sig}
</div>`;

return [{ json: { html, subject: `EDIT Day 2 subject line — ${L.firstName}`, to: L.email } }];

// DAY 4 — Direct offer pitch: book the call / consultation
const C = $('Setup Client Variables').item.json;
const L = $('Capture Lead Data').item.json;

const sig = `<div style="margin-top:40px;display:flex;align-items:center;border-top:1px solid #e2e8f0;padding-top:30px;">
  <img src="${C.photoUrl}" alt="${C.senderFirstName}" style="width:70px;height:70px;border-radius:50%;margin-right:20px;object-fit:cover;border:2px solid #e2e8f0;">
  <div>
    <p style="margin:0;font-weight:800;font-size:18px;color:#1a1a2e;">${C.senderFullName}</p>
    <p style="margin:4px 0 0 0;font-size:14px;color:#64748b;font-weight:600;">${C.senderTitle}</p>
    <p style="margin:4px 0 0 0;font-size:13px;"><a href="${C.siteUrl}" style="color:#3b82f6;text-decoration:none;font-weight:600;">${C.siteUrl.replace('https://','')}</a></p>
  </div>
</div>`;

// ============================================================
// EDIT EMAIL BODY — Day 4: The direct ask
// Goal: invite them to take the next step (book a call, session, consult)
// This is the first real pitch — keep it personal and low-pressure
// ============================================================
const body = `
  <h2 style="font-size:24px;font-weight:800;color:#1a1a2e;margin-bottom:24px;letter-spacing:-0.5px;">EDIT: Direct, personal subject hook</h2>
  <p style="font-size:16px;margin-bottom:20px;">Hi ${L.firstName},</p>
  <p style="font-size:16px;margin-bottom:20px;">I've been sharing some thoughts with you over the past week and it seems like you're looking for EDIT — describe what they're trying to achieve.</p>
  <p style="font-size:16px;margin-bottom:20px;">EDIT — 1-2 lines about the gap between where they are and where they want to be. Make it specific to their situation.</p>
  <div style="text-align:center;margin:40px 0;background:linear-gradient(135deg,rgba(59,130,246,0.05),rgba(139,92,246,0.05));padding:40px 20px;border-radius:12px;border:1px solid rgba(59,130,246,0.1);">
    <h3 style="margin-top:0;color:#1a1a2e;font-size:18px;margin-bottom:20px;">EDIT — Name of the offer (e.g. Free Strategy Call / Free Consultation)</h3>
    <a href="${C.bookingUrl}" style="background-color:#3b82f6;color:white;padding:16px 32px;text-decoration:none;border-radius:8px;font-weight:bold;font-size:16px;display:inline-block;box-shadow:0 4px 14px rgba(59,130,246,0.3);">EDIT — CTA Button Text</a>
  </div>
  <p style="font-size:16px;margin-bottom:20px;">EDIT — Optional: add a trust statement here. What happens on the call? How long? What do they walk away with?</p>
  <p style="font-size:16px;margin-bottom:30px;">Talk soon,</p>
`;
// ============================================================

const html = `<div style="font-family:'Helvetica Neue',Arial,sans-serif;color:#1a1a2e;max-width:600px;margin:0 auto;padding:40px 20px;line-height:1.6;background-color:#ffffff;border-top:5px solid #3b82f6;border-radius:8px;box-shadow:0 4px 6px rgba(0,0,0,0.05);">
  <div style="text-align:center;margin-bottom:40px;"><img src="${C.logoUrl}" alt="${C.companyName}" style="max-height:50px;"></div>
  ${body}
  ${sig}
</div>`;

return [{ json: { html, subject: `EDIT Day 4 subject line — ${L.firstName}`, to: L.email } }];

// DAY 7 — Social proof / results / what others are experiencing
const C = $('Setup Client Variables').item.json;
const L = $('Capture Lead Data').item.json;

const sig = `<div style="margin-top:40px;display:flex;align-items:center;border-top:1px solid #e2e8f0;padding-top:30px;">
  <img src="${C.photoUrl}" alt="${C.senderFirstName}" style="width:70px;height:70px;border-radius:50%;margin-right:20px;object-fit:cover;border:2px solid #e2e8f0;">
  <div>
    <p style="margin:0;font-weight:800;font-size:18px;color:#1a1a2e;">${C.senderFullName}</p>
    <p style="margin:4px 0 0 0;font-size:14px;color:#64748b;font-weight:600;">${C.senderTitle}</p>
    <p style="margin:4px 0 0 0;font-size:13px;"><a href="${C.siteUrl}" style="color:#3b82f6;text-decoration:none;font-weight:600;">${C.siteUrl.replace('https://','')}</a></p>
  </div>
</div>`;

// ============================================================
// EDIT EMAIL BODY — Day 7: Social proof + re-pitch
// Goal: show what others are experiencing/achieving, reinforce the offer
// Use a testimonial, a result, or a "what we're seeing" observation
// ============================================================
const body = `
  <h2 style="font-size:24px;font-weight:800;color:#1a1a2e;margin-bottom:24px;letter-spacing:-0.5px;">What ${L.serviceInterest} businesses are doing differently right now</h2>
  <p style="font-size:16px;margin-bottom:20px;">Hi ${L.firstName},</p>
  <p style="font-size:16px;margin-bottom:20px;">EDIT — Open with an observation about what the best businesses in their space are doing differently. Can use a client story (anonymized or named with permission), a stat, or a pattern you're seeing.</p>
  <div style="background-color:#f8fafc;padding:24px;border-left:4px solid #3b82f6;border-radius:4px;margin:30px 0;">
    <p style="font-size:15px;margin:0 0 12px 0;font-weight:700;color:#1a1a2e;">EDIT — Small headline for this section (e.g. "What's working right now:")</p>
    <p style="font-size:15px;margin:6px 0;color:#475569;">✅ <strong>EDIT result or capability #1</strong></p>
    <p style="font-size:15px;margin:6px 0;color:#475569;">✅ <strong>EDIT result or capability #2</strong></p>
    <p style="font-size:15px;margin:6px 0;color:#475569;">✅ <strong>EDIT result or capability #3</strong></p>
  </div>
  <p style="font-size:16px;margin-bottom:20px;">EDIT — 1-2 sentences connecting those results to the call/offer.</p>
  <div style="text-align:center;margin:40px 0;">
    <a href="${C.bookingUrl}" style="background-color:#8b5cf6;color:white;padding:16px 32px;text-decoration:none;border-radius:8px;font-weight:bold;font-size:16px;display:inline-block;box-shadow:0 4px 14px rgba(139,92,246,0.3);">EDIT — CTA Button Text</a>
  </div>
  <p style="font-size:16px;margin-bottom:30px;">Talk soon,</p>
`;
// ============================================================

const html = `<div style="font-family:'Helvetica Neue',Arial,sans-serif;color:#1a1a2e;max-width:600px;margin:0 auto;padding:40px 20px;line-height:1.6;background-color:#ffffff;border-top:5px solid #8b5cf6;border-radius:8px;box-shadow:0 4px 6px rgba(0,0,0,0.05);">
  <div style="text-align:center;margin-bottom:40px;"><img src="${C.logoUrl}" alt="${C.companyName}" style="max-height:50px;"></div>
  ${body}
  ${sig}
</div>`;

return [{ json: { html, subject: `What ${L.serviceInterest} businesses are doing differently, ${L.firstName}`, to: L.email } }];

// DAY 10 — Final breakup email. Low pressure. Leave the door open.
const C = $('Setup Client Variables').item.json;
const L = $('Capture Lead Data').item.json;

const sig = `<div style="margin-top:40px;display:flex;align-items:center;border-top:1px solid #e2e8f0;padding-top:30px;">
  <img src="${C.photoUrl}" alt="${C.senderFirstName}" style="width:70px;height:70px;border-radius:50%;margin-right:20px;object-fit:cover;border:2px solid #e2e8f0;">
  <div>
    <p style="margin:0;font-weight:800;font-size:18px;color:#1a1a2e;">${C.senderFullName}</p>
    <p style="margin:4px 0 0 0;font-size:14px;color:#64748b;font-weight:600;">${C.senderTitle}</p>
    <p style="margin:4px 0 0 0;font-size:13px;"><a href="${C.siteUrl}" style="color:#3b82f6;text-decoration:none;font-weight:600;">${C.siteUrl.replace('https://','')}</a></p>
  </div>
</div>`;

// ============================================================
// EDIT EMAIL BODY — Day 10: The breakup. 
// Goal: final CTA, leave door open, no hard feelings
// This often converts the people who were almost ready — because it's real
// ============================================================
const body = `
  <h2 style="font-size:24px;font-weight:800;color:#1a1a2e;margin-bottom:24px;letter-spacing:-0.5px;">Closing the loop, ${L.firstName}.</h2>
  <p style="font-size:16px;margin-bottom:20px;">Hi ${L.firstName},</p>
  <p style="font-size:16px;margin-bottom:20px;">I've sent a few emails over the past couple of weeks and I don't want to keep showing up in your inbox if the timing isn't right.</p>
  <p style="font-size:16px;margin-bottom:20px;">But before I close the loop — if you've been curious about EDIT (what the client offers), I want to make this as easy as possible:</p>
  <div style="background-color:#f8fafc;padding:24px;border-left:4px solid #3b82f6;border-radius:4px;margin:30px 0;">
    <p style="font-size:15px;margin:0;font-style:italic;color:#475569;">EDIT — Describe the offer one final time. Make it sound easy, low-stakes, and genuinely helpful. E.g. "The (offer name) is 30 minutes. No pitch. No pressure. You'll walk away with (specific outcome)."</p>
  </div>
  <div style="text-align:center;margin:40px 0;">
    <a href="${C.bookingUrl}" style="background-color:#3b82f6;color:white;padding:16px 32px;text-decoration:none;border-radius:8px;font-weight:bold;font-size:16px;display:inline-block;box-shadow:0 4px 14px rgba(59,130,246,0.3);">EDIT — Final CTA Button Text</a>
  </div>
  <p style="font-size:16px;margin-bottom:20px;">If now isn't the right time, no worries at all. You can always reach me at <a href="mailto:${C.replyToEmail}" style="color:#3b82f6;text-decoration:none;font-weight:600;">${C.replyToEmail}</a> whenever you're ready.</p>
  <p style="font-size:16px;margin-bottom:30px;">Either way — I'm rooting for you.</p>
  <p style="font-size:16px;margin-bottom:30px;">${C.senderFirstName}</p>
`;
// ============================================================

const html = `<div style="font-family:'Helvetica Neue',Arial,sans-serif;color:#1a1a2e;max-width:600px;margin:0 auto;padding:40px 20px;line-height:1.6;background-color:#ffffff;border-top:5px solid #64748b;border-radius:8px;box-shadow:0 4px 6px rgba(0,0,0,0.05);">
  <div style="text-align:center;margin-bottom:40px;"><img src="${C.logoUrl}" alt="${C.companyName}" style="max-height:50px;"></div>
  ${body}
  ${sig}
</div>`;

return [{ json: { html, subject: `Closing the loop, ${L.firstName}.`, to: L.email } }];
